import 'package:flutter/material.dart';

/// Path of the PolyCheck logo, generated by `scripts/generate-brand-assets.py`.
const String productLogoAsset = 'assets/branding/brand-mark.png';

/// The PolyCheck product logo. The institution is named in text (and by its
/// monogram on ID cards); this mark is the app's own.
class ProductLogo extends StatelessWidget {
  const ProductLogo({super.key, this.size = 64});

  final double size;

  @override
  Widget build(BuildContext context) {
    return Image.asset(
      productLogoAsset,
      width: size,
      height: size,
      filterQuality: FilterQuality.medium,
      semanticLabel: 'PolyCheck logo',
    );
  }
}
